package io.fireflysoftware.experience.lending.web.openapi;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.JsonNode;
import io.swagger.v3.core.util.Yaml;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

/** Full genuine controller capture, not a handwritten specification or a business operation. */
class ApplicationEvidenceProducerCoverageIT {
    @Test void actualWholeProducerRetainsEveryExistingOperationAndCorrectsExistingUploadWithOneRecoveryAddition()throws Exception{
        var mapper=Yaml.mapper().copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);var before=mapper.readTree(read("lending.evidence.experience.producer.original"));var after=mapper.readTree(read("lending.evidence.experience.producer.candidate"));String base="/api/v1/experience/lending/applications/{id}/documents";var old=operations(before);assertThat(old).hasSize(95).contains(List.of(base,"post","uploadDocument"));var expected=new HashSet<>(old);assertThat(expected.add(List.of(base+"/actions/{actionId}/recovery","post","recoverApplicationDocumentEvidence"))).isTrue();String initial="/api/v1/experience/lending/applications/{applicationId}/initial-primary-contracts/actions/{actionId}";
        assertThat(expected.add(List.of(initial,"post","linkApplicationInitialPrimaryContract"))).isTrue();assertThat(expected.add(List.of(initial,"get","observeApplicationInitialPrimaryContract"))).isTrue();assertThat(operations(after)).containsExactlyInAnyOrderElementsOf(expected);
        var current=mapper.readTree(read("lending.initial-contract.experience.producer.current"));assertThat(operations(current)).hasSize(96);current.path("paths").properties().forEach(path->assertThat(after.path("paths").path(path.getKey())).isEqualTo(path.getValue()));current.path("components").path("schemas").properties().forEach(schema->assertThat(after.path("components").path("schemas").path(schema.getKey())).isEqualTo(schema.getValue()));assertThat(after.path("components").path("securitySchemes")).isEqualTo(current.path("components").path("securitySchemes"));
        for(String verb:List.of("post","get")){var operation=after.path("paths").path(initial).path(verb);for(String code:verb.equals("post")?List.of("200","201"):List.of("200"))assertThat(operation.path("responses").path(code).path("content").path("application/json").path("schema").path("$ref").asText()).isEqualTo("#/components/schemas/ApplicationInitialContractReceipt");for(String code:verb.equals("post")?List.of("409","503"):List.of("503"))assertThat(operation.path("responses").path(code).path("content").path("application/json").path("schema").path("$ref").asText()).isEqualTo("#/components/schemas/ApplicationInitialContractError");assertThat(operation.path("security").findValues("lendingExperienceIntakeBearer")).hasSize(1);if(verb.equals("post")){for(var parameter:operation.path("parameters"))assertThat(parameter.path("name").asText()).isNotEqualToIgnoringCase("X-Idempotency-Key");}else assertThat(operation.path("responses").path("204").has("content")).isFalse();}
        var initialSchemas=after.path("components").path("schemas");var initialRequest=initialSchemas.path("ApplicationInitialContractRequest");var fields=new HashSet<String>();initialRequest.path("properties").fieldNames().forEachRemaining(fields::add);assertThat(fields).containsExactlyInAnyOrder("actionId","existingContractId");assertThat(initialSchemas.path("ApplicationInitialContractReceipt").path("properties").path("linkedAt").path("$ref").asText()).isEqualTo("#/components/schemas/FireflyInstant");
        before.path("paths").properties().forEach(path->{if(!path.getKey().equals(base))assertThat(after.path("paths").path(path.getKey())).isEqualTo(path.getValue());else path.getValue().properties().forEach(operation->{if(!operation.getKey().equals("post"))assertThat(after.path("paths").path(base).path(operation.getKey())).isEqualTo(operation.getValue());});});
        before.path("components").path("schemas").properties().forEach(schema->{if(!Set.of("ApplicationDocumentDTO","UploadDocumentCommand").contains(schema.getKey()))assertThat(after.path("components").path("schemas").path(schema.getKey())).isEqualTo(schema.getValue());});
        for(String suffix:List.of("","/actions/{actionId}/recovery")){var operation=after.path("paths").path(base+suffix).path("post");for(String code:List.of("200","201"))assertThat(operation.path("responses").path(code).path("content").path("application/json").path("schema").path("$ref").asText()).isEqualTo("#/components/schemas/ApplicationDocumentDTO");for(String code:List.of("409","503"))assertThat(operation.path("responses").path(code).path("content").path("application/json").path("schema").path("$ref").asText()).isEqualTo("#/components/schemas/ApplicationEvidenceError");assertThat(operation.path("security").findValues("lendingExperienceIntakeBearer")).hasSize(1);for(var parameter:operation.path("parameters"))assertThat(parameter.path("name").asText()).isNotEqualToIgnoringCase("X-Idempotency-Key");}
        var schemas=after.path("components").path("schemas");var request=schemas.path("UploadDocumentCommand");var required=new HashSet<String>();request.path("required").forEach(value->required.add(value.asText()));assertThat(required).contains("actionId","content");var content=request.path("properties").path("content");assertThat(content.path("type").asText()).isEqualTo("string");assertThat(content.path("format").asText()).isEqualTo("byte");assertThat(content.path("maxLength").asInt()).isEqualTo(2796204);assertThat(content.path("writeOnly").asBoolean()).isFalse();assertThat(request.path("properties").has("partyId")).isFalse();assertThat(request.path("properties").path("fileName").path("maxLength").asInt()).isEqualTo(200);
        var receipt=schemas.path("ApplicationDocumentDTO").path("properties");assertThat(receipt.has("associationId")).isTrue();assertThat(receipt.has("storedDocumentId")).isTrue();assertThat(receipt.path("documentId").path("description").asText()).contains("association");for(String field:List.of("storedAt","attachedAt"))assertThat(receipt.path(field).path("$ref").asText()).isEqualTo("#/components/schemas/FireflyInstant");assertThat(schemas.path("FireflyInstant").path("format").asText()).isEqualTo("date-time");
        Files.writeString(Path.of(System.getProperty("lending.evidence.experience.producer.coverage")),new com.fasterxml.jackson.databind.ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(Map.of("originalOperations",old,"actualOperations",operations(after),"existingUploadCorrected",true,"unrelatedPathAndSchemaNodesPreserved",true,"allCurrent96PathAndSchemaNodesPreserved",true,"nativeYamlSemanticComparison",true))+"\n");
    }
    static Set<List<String>> operations(JsonNode document){var result=new TreeSet<List<String>>(Comparator.comparing(Object::toString));var verbs=Set.of("get","post","put","patch","delete","head","options","trace");assertThat(document.path("openapi").asText()).startsWith("3.");document.path("paths").properties().forEach(path->path.getValue().properties().forEach(operation->{if(verbs.contains(operation.getKey())){String id=operation.getValue().path("operationId").asText();assertThat(id).isNotBlank();assertThat(result.add(List.of(path.getKey(),operation.getKey(),id))).isTrue();}}));return result;}
    static byte[] read(String property)throws Exception{var path=Path.of(Objects.requireNonNull(System.getProperty(property)));assertThat(path).isAbsolute();assertThat(Files.isRegularFile(path)&&!Files.isSymbolicLink(path)).isTrue();byte[] bytes=Files.readAllBytes(path);assertThat(bytes.length).isBetween(1,4194304);return bytes;}
}
